import RecallCore
import SwiftUI

enum GradeRecorder {
    @MainActor static func record(card: Card, grade: Grade, clock: Clock, context: ModelContext) throws {
        // Update card's schedule using SM2Engine
        let newSchedule = SM2Engine.schedule(current: CardSchedule(easeFactor: card.easeFactor, 
                                                                   intervalDays: card.intervalDays, 
                                                                   repetitions: card.repetitions, 
                                                                   nextReviewDate: card.nextReviewDate), 
                                             grade: grade, 
                                             now: clock.now(), 
                                             clock: clock)
        card.easeFactor = newSchedule.easeFactor
        card.intervalDays = newSchedule.intervalDays
        card.repetitions = newSchedule.repetitions
        card.nextReviewDate = newSchedule.nextReviewDate

        // Insert ReviewLogEntry
        let logEntry = ReviewLogEntry(id: UUID(), 
                                     timestamp: clock.now(), 
                                     gradeRaw: grade.rawValue, 
                                     cardID: card.id, 
                                     deckID: card.deck?.id ?? UUID(uuidString: "00000000-0000-0000-0000-000000000000"),  // Default UUID if no deck
                                     isDemo: card.isDemo)
        context.insert(logEntry)

        // Save the context
        try context.save()
    }
}
```

